import React, { useEffect, useState } from "react";
import ReactQuill from "react-quill";
import "react-quill/dist/quill.snow.css";
import "../styles/main.css";

export default function AdminManageHome() {
  const [data, setData] = useState({
    bannerVideos: [],
    welcomeText: "",
    activityImages: [],
    threeCol: [],
    testimonials: [],
  });

  useEffect(() => {
    // Example: fetching data from your API
    fetch("http://localhost:5000/api/admin/home")
      .then((res) => res.json())
      .then((resData) => {
        setData({
          bannerVideos: resData.bannerVideos || [],
          welcomeText: resData.welcomeText || "",
          activityImages: resData.activityImages || [],
          threeCol: resData.threeCol || [],
          testimonials: resData.testimonials || [],
        });
      })
      .catch((err) => console.error("Error loading home data:", err));
  }, []);

  return (
    <div className="admin-manage-home">
      <h1 className="page-title">🏠 Manage Home Page</h1>

      {/* --- Video Banner Section --- */}
      <section className="admin-section">
        <h2>🎥 Banner Videos</h2>
        <div className="video-preview-grid">
          {data.bannerVideos?.length > 0 ? (
            data.bannerVideos.map((video, i) => (
              <video
                key={i}
                src={video}
                controls
                className="admin-video-thumb"
              />
            ))
          ) : (
            <p className="empty-msg">No banner videos added yet</p>
          )}
        </div>
      </section>

      {/* --- Welcome Section --- */}
      <section className="admin-section">
        <h2>👋 Welcome Text</h2>
        <ReactQuill
          theme="snow"
          value={data.welcomeText}
          onChange={(val) => setData({ ...data, welcomeText: val })}
        />
      </section>

      {/* --- Activities Section --- */}
      <section className="admin-section">
        <h2>🏫 Activities Images</h2>
        <div className="activity-preview-grid">
          {data.activityImages?.length > 0 ? (
            data.activityImages.map((img, i) => (
              <img key={i} src={img} alt="activity" className="admin-img-thumb" />
            ))
          ) : (
            <p className="empty-msg">No activity images added yet</p>
          )}
        </div>
      </section>

      {/* --- 3 Column Section --- */}
      <section className="admin-section">
        <h2>📰 3-Column Section</h2>
        <div className="three-col-preview">
          {data.threeCol?.length > 0 ? (
            data.threeCol.map((col, i) => (
              <div key={i} className="three-col-card">
                <h4>{col.title}</h4>
                <p>{col.text}</p>
              </div>
            ))
          ) : (
            <p className="empty-msg">No 3-column data yet</p>
          )}
        </div>
      </section>

      {/* --- Testimonials --- */}
      <section className="admin-section">
        <h2>💬 Testimonials</h2>
        <div className="testimonials-preview">
          {data.testimonials?.length > 0 ? (
            data.testimonials.map((vid, i) => (
              <video
                key={i}
                src={vid}
                controls
                className="admin-video-thumb"
              />
            ))
          ) : (
            <p className="empty-msg">No testimonial videos added yet</p>
          )}
        </div>
      </section>
    </div>
  );
}
